create extension if not exists pgcrypto;
create table if not exists public.tenants (tenant_id varchar(64) primary key,name varchar(200) not null,created_at timestamptz not null default now());
create table if not exists public.users (user_id varchar(64) primary key,tenant_id varchar(64) not null references public.tenants(tenant_id) on delete cascade,email varchar(320) not null unique,password_hash varchar(512) not null default '',role varchar(24) not null default 'viewer',is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.refresh_tokens (token_hash varchar(64) primary key,user_id varchar(64) not null references public.users(user_id) on delete cascade,tenant_id varchar(64) not null references public.tenants(tenant_id) on delete cascade,expires_at timestamptz not null,revoked boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.scan_jobs (job_id varchar(64) primary key,tenant_id varchar(64) not null references public.tenants(tenant_id) on delete cascade,job_type varchar(32) not null,target varchar(2048) not null,status varchar(24) not null,progress integer not null default 0,current_engine varchar(64),logs jsonb not null default '[]'::jsonb,payload jsonb not null default '{}'::jsonb,result jsonb,error_message text,created_at timestamptz not null default now(),started_at timestamptz,finished_at timestamptz);
create table if not exists public.scans (scan_id varchar(64) primary key,tenant_id varchar(64) not null references public.tenants(tenant_id) on delete cascade,job_id varchar(64),scan_kind varchar(32) not null,target varchar(2048) not null,status varchar(24) not null,result jsonb,error_message text,created_at timestamptz not null default now(),finished_at timestamptz);
create table if not exists public.assets (asset_id varchar(64) primary key,tenant_id varchar(64) not null references public.tenants(tenant_id) on delete cascade,target varchar(2048) not null,data jsonb not null default '{}'::jsonb,first_seen timestamptz not null default now(),last_seen timestamptz not null default now());
create table if not exists public.audit_logs (id varchar(64) primary key,tenant_id varchar(64) not null references public.tenants(tenant_id) on delete cascade,event varchar(64) not null,target varchar(2048),data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_scan_jobs_tenant_created on public.scan_jobs(tenant_id,created_at desc);
create index if not exists idx_scans_tenant_created on public.scans(tenant_id,created_at desc);
create index if not exists idx_assets_tenant_last_seen on public.assets(tenant_id,last_seen desc);
create index if not exists idx_audit_logs_tenant_created on public.audit_logs(tenant_id,created_at desc);
do $$ declare t text; begin foreach t in array array['scan_jobs','scans','assets','audit_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('alter table public.%I force row level security',t); execute format('drop policy if exists tenant_isolation on public.%I',t); execute format('create policy tenant_isolation on public.%I using (tenant_id = current_setting(''app.tenant_id'', true)) with check (tenant_id = current_setting(''app.tenant_id'', true))',t); end loop; end $$;

create index if not exists idx_users_tenant_created on public.users(tenant_id,created_at);
-- Tenant-scoped operational data is protected by RLS. The users/tenants tables
-- remain server-managed because initial provisioning and Supabase Auth callbacks
-- need a bootstrap path; browser clients never receive the database credentials.


-- Admin Security Center
create table if not exists public.admin_settings (tenant_id varchar(64) primary key references public.tenants(tenant_id) on delete cascade, security_policy jsonb not null default '{}'::jsonb, scan_policy jsonb not null default '{}'::jsonb, ai_policy jsonb not null default '{}'::jsonb, notification_policy jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.feature_flags (tenant_id varchar(64) primary key references public.tenants(tenant_id) on delete cascade, flags jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.admin_api_keys (key_id varchar(64) primary key, tenant_id varchar(64) not null references public.tenants(tenant_id) on delete cascade, user_id varchar(64) not null references public.users(user_id) on delete cascade, name varchar(120) not null, key_hash varchar(64) not null unique, scopes jsonb not null default '[]'::jsonb, expires_at timestamptz, last_used_at timestamptz, revoked boolean not null default false, created_at timestamptz not null default now());
create index if not exists idx_admin_api_keys_tenant_created on public.admin_api_keys(tenant_id,created_at desc);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['admin_settings','feature_flags','admin_api_keys'] LOOP EXECUTE format('alter table public.%I enable row level security',t); EXECUTE format('alter table public.%I force row level security',t); EXECUTE format('drop policy if exists tenant_isolation on public.%I',t); EXECUTE format('create policy tenant_isolation on public.%I using (tenant_id = current_setting(''app.tenant_id'', true)) with check (tenant_id = current_setting(''app.tenant_id'', true))',t); END LOOP; END $$;
